presetParts.perFrame:
dec_med = exp(-7/fps);
dec_slow = exp(-2/fps);
beat = max (max (bass, mid), treb); 
avg = avg*dec_slow + beat*(1-dec_slow);
is_beat = above(beat, .5+avg+peak) * above (time, t0+.2);
t0 = is_beat*time + (1-is_beat)*t0;
peak = is_beat * beat + (1-is_beat)*peak*dec_med;
index = (index + is_beat) %8;
index2 = (index2 + is_beat*bnot(index))%4;
index3 = (index3 + is_beat*bnot(index)*bnot(index2))%3;

monitor = index4;

q20 = avg;
q21 = beat;
q22 = peak;
q23 = index;
q24 = is_beat;
q26 = bass_att + mid_att + treb_att+1;

q20 = max(q20-1,0);
op1 = dec_med*op1 + q20*(1-dec_med);
op2 = dec_med*op2 + q20*op1;

q10 = atan(op2*1.5)*1.2;

//k1 =  is_beat*bnot(index)*bnot(index2);

k1 =  is_beat*equal(index,0);
p1 =  k1*(p1+1) + (1-k1)*p1;
p2 = dec_slow * p2+ (1-dec_slow)*p1;
p3 = dec_slow * p3+ (1-dec_slow)*p2;
rott = p3 * 3.14159265359/4;


q27 = 8-index;
q28 = index2;

//q28 = sin(time)+1;

q1 = cos(rott);
q2 = sin(rott);
q3 = -q2;
q4 = q1;

t_rel = t_rel + .02*30/fps*q1*q1;

q5 = cos(t_rel);
q6 = sin(t_rel);
q7 = -q6;
q8 = q5;

puls1 = puls1*dec_med + q24*(1-dec_med);
puls2 = puls2*dec_med + puls1*(1-dec_med);
q25 = puls2;

roty = roty + .003*30/fps;
q29=roty;

zoom = 1+.0*q22;

